import React, { useEffect, useState } from 'react';
import { FaPlane } from 'react-icons/fa';
import { useTheme } from '../context/ThemeContext';

const DecorativePlanes = () => {
  const { theme } = useTheme();
  const [planes, setPlanes] = useState([]);

  const calculateRotation = (startX, startY, endX, endY) => {
    const angle = Math.atan2(endY - startY, endX - startX) * (180 / Math.PI);
    return angle;
  };

  const generateControlPoints = (startX, startY, endX, endY) => {
    // Generate two control points for a cubic Bezier curve
    const distance = Math.sqrt(Math.pow(endX - startX, 2) + Math.pow(endY - startY, 2));
    const maxOffset = distance * 0.5; // Maximum offset for control points

    // Control point 1
    const cp1x = startX + (Math.random() - 0.5) * maxOffset;
    const cp1y = startY + (Math.random() - 0.5) * maxOffset;

    // Control point 2
    const cp2x = endX + (Math.random() - 0.5) * maxOffset;
    const cp2y = endY + (Math.random() - 0.5) * maxOffset;

    return { cp1x, cp1y, cp2x, cp2y };
  };

  const generateNewPath = (currentX, currentY) => {
    const endX = Math.random() * 100;
    const endY = Math.random() * 100;
    const { cp1x, cp1y, cp2x, cp2y } = generateControlPoints(currentX, currentY, endX, endY);
    
    return {
      endX,
      endY,
      cp1x,
      cp1y,
      cp2x,
      cp2y,
      rotation: calculateRotation(currentX, currentY, endX, endY)
    };
  };

  useEffect(() => {
    // Create initial planes
    const initialPlanes = Array.from({ length: 5 }, (_, index) => {
      const startX = Math.random() * 100;
      const startY = Math.random() * 100;
      const path = generateNewPath(startX, startY);
      
      return {
        id: index,
        startX,
        startY,
        ...path,
        duration: 8 + Math.random() * 7,
        delay: Math.random() * 5,
        size: 12 + Math.random() * 8,
        pathProgress: 0
      };
    });
    setPlanes(initialPlanes);

    // Update plane positions periodically
    const interval = setInterval(() => {
      setPlanes(currentPlanes => 
        currentPlanes.map(plane => {
          const newPath = generateNewPath(plane.endX, plane.endY);
          return {
            ...plane,
            startX: plane.endX,
            startY: plane.endY,
            ...newPath,
            duration: 8 + Math.random() * 7,
            delay: 0,
            pathProgress: 0
          };
        })
      );
    }, 15000);

    // Update path progress for smoother curves
    const progressInterval = setInterval(() => {
      setPlanes(currentPlanes =>
        currentPlanes.map(plane => ({
          ...plane,
          pathProgress: (plane.pathProgress + 0.01) % 1
        }))
      );
    }, 50);

    return () => {
      clearInterval(interval);
      clearInterval(progressInterval);
    };
  }, []);

  const getBezierPoint = (t, x0, y0, x1, y1, x2, y2, x3, y3) => {
    const cx = 3 * (x1 - x0);
    const bx = 3 * (x2 - x1) - cx;
    const ax = x3 - x0 - cx - bx;

    const cy = 3 * (y1 - y0);
    const by = 3 * (y2 - y1) - cy;
    const ay = y3 - y0 - cy - by;

    const x = ax * Math.pow(t, 3) + bx * Math.pow(t, 2) + cx * t + x0;
    const y = ay * Math.pow(t, 3) + by * Math.pow(t, 2) + cy * t + y0;

    return { x, y };
  };

  return (
    <div className="fixed inset-0 pointer-events-none overflow-hidden" style={{ zIndex: 0 }}>
      {planes.map(plane => {
        const { x, y } = getBezierPoint(
          plane.pathProgress,
          plane.startX,
          plane.startY,
          plane.cp1x,
          plane.cp1y,
          plane.cp2x,
          plane.cp2y,
          plane.endX,
          plane.endY
        );

        return (
          <div
            key={plane.id}
            className="absolute"
            style={{
              left: `${x}%`,
              top: `${y}%`,
              transform: `rotate(${plane.rotation}deg)`,
              transition: 'transform 0.1s linear',
              opacity: 0.3,
              color: theme.primary
            }}
          >
            <FaPlane size={plane.size} />
          </div>
        );
      })}
    </div>
  );
};

export default DecorativePlanes;
